import CADCore
import Foundation
import simd
import Testing
@testable import CADKernel

/// The top edges of a shoe sole are rounded by a 7.5 mm circle swept along each long side, which ends in the
/// 22 mm plan corners. Where the swept round meets a corner there is a short crease. The sketch's circle sits 0.02 mm
/// beyond the side wall instead of exactly tangent to it, so the two faces meet at about 4 degrees at one end of
/// the crease and run on at 70 degrees at the other. OCCT ends a round only where faces are tangent to within 0.01
/// radian, and refused to round that crease at any size, although Fusion rounds it without trouble.
@Suite struct FadingCreaseRoundTests {
    /// The sole's shell, its corner rounding and the swept round: the features up to Sweep1 of a real model.
    private func sole() throws -> CADDocument {
        try CADDocument.decode(Data(soleJSON.utf8))
    }

    /// The two creases at the rear corners, which are mirror images of each other.
    private let creases = ["6548f37e.side.6383355c|shell_round.side.c78d022f",
                           "6548f37e.side.dd3c3d03~6383355c|shell_round.side.6fa85536"]

    @Test func aCreaseThatFadesOutIntoTangentFacesCanBeRounded() throws {
        let doc = try sole()
        let before = Regenerator.regenerate(doc)
        #expect(before.errors.isEmpty, "\(before.errors)")
        let shell = try #require(before.body("shell"))
        for crease in creases {
            #expect(shell.hasEdge(crease), "the crease \(crease) exists")
            for size in ["1 mm", "2 mm", "4 mm"] {
                var d = doc
                d.features.append(Feature(id: "fx", name: "Fillet2", .fillet(EdgeFeature(edges: [EdgeRef(body: "shell", edge: crease)], size: size))))
                let r = Regenerator.regenerate(d)
                #expect(r.errors.isEmpty, "a \(size) round of \(crease): \(r.errors)")
                let after = try #require(r.body("shell"))
                try expectSmallRound(after, before: shell, size: size, crease: crease)
            }
        }
    }

    /// The same shell with the 0.6 mm slit cut through it that splits the sole in two. The face merge that follows a
    /// boolean leaves the faces in an order in which OCCT's fillet cannot finish the crease at the nose end, at any
    /// size, though it rounds it before the cut; the fillet builds the body again with its faces the other way round
    /// when it fails.
    @Test func aCreaseStillRoundsAfterABooleanReorderedTheFaces() throws {
        let doc = try CADDocument.decode(Data(slitSoleJSON.utf8))
        let before = Regenerator.regenerate(doc)
        #expect(before.errors.isEmpty, "\(before.errors)")
        let shell = try #require(before.body("shell"))
        let crease = "6548f37e.side.dd3c3d03~6383355c|shell_round.side.f75daf23"
        #expect(shell.hasEdge(crease), "the crease \(crease) exists")
        for size in ["1 mm", "4 mm", "5 mm"] {
            var d = doc
            d.features.append(Feature(id: "fx", name: "Fillet2", .fillet(EdgeFeature(edges: [EdgeRef(body: "shell", edge: crease)], size: size))))
            let r = Regenerator.regenerate(d)
            #expect(r.errors.isEmpty, "a \(size) round of \(crease): \(r.errors)")
            let after = try #require(r.body("shell"))
            try expectSmallRound(after, before: shell, size: size, crease: crease)
            #expect(after.faceNames.contains { $0.hasPrefix("fx.fillet") }, "the round is in the body")
        }
    }

    /// The round is a small patch along the crease and takes a sliver of material: a round of r mm on a crease some
    /// 16 mm long takes at most 0.2146 r² of it per millimetre, and less where the crease fades. (The volume integral
    /// of a body this size is good to a few cubic millimetres only, so that check is wide; the round's own face, which
    /// OCCT names after the crease, must also stay within a few millimetres of it.)
    private func expectSmallRound(_ after: KBody, before: KBody, size: String, crease: String) throws {
        let r0 = Double(size.dropLast(3))!
        let taken = before.volume - after.volume
        #expect(abs(taken) < 10 + 0.2146 * r0 * r0 * 16, "\(size) round of \(crease) took \(taken) mm³")
        let mesh = try after.tessellate(linearDeflection: 0.05, angularDeflection: 0.2)
        let face = try #require(mesh.faceNames.firstIndex(of: "fx.fillet." + crease), "the round's face exists")
        var low = SIMD3<Float>(repeating: .infinity), high = SIMD3<Float>(repeating: -.infinity)
        for t in 0..<mesh.triangleFace.count where Int(mesh.triangleFace[t]) == face {
            for k in 0..<3 {
                let v = Int(mesh.indices[t * 3 + k])
                let p = SIMD3<Float>(mesh.positions[v * 3], mesh.positions[v * 3 + 1], mesh.positions[v * 3 + 2])
                low = simd_min(low, p)
                high = simd_max(high, p)
            }
        }
        let extent = high - low
        #expect(extent.max() > 1 && extent.max() < 25, "\(size) round of \(crease): its face is \(extent) mm across")
    }

